MY50 = {
"0_00294_00": "اِنُّهْ بَقَى بِيزْنِسْ مُودِلْ نَاجِحْ وِمُشْ بَسْ بِيُوَفِّرْ فُرَصْ عَمَلْ لِلشَّبَابْ دَهْ كَمَانْ بِيْدَخِّلْ عُمْلَة صَعْبَة لِلْبَلَدْ اِذَا",
"0_00972_00": "لِلْمُسْتَمِعْ يِفَكِّرْ فِيهْ فِي عَالَمْ اِلسُوشْيَالْ مِيدْيَا اِلْلِي مَبْنِي عَلَى اِلْمُشَارَكَة اِزَّاي مُمْكِنْ نِلَاقِي اِلتُّوَازُنْ اِلصَّعْبْ",
"0_01035_00": "اِلتَّقْرِيرْ بِيشْرَحْ اِسْتِرَاتِيجِيَّاتْ نَفْسِيَّة وَاضْحَة جِدَاً أَوَّلْ حَاجَة هِيَ اِلتَّصْمِيمْ اِلْهِنْدِسِي",
"0_01107_00": "وِخَلَّى اِلنَّفَسْ اِلْبَيْتِي مُتَاحْ دِلِيفْرِي دِي ظَاهِرَة مُسَيِّرَة جِدَاً وِحَلَّتْ مُشْكِلَة لِنَاسْ كَتِيرْ مَا",
"0_01199_02": "يِتْفَرَّجْ عَلَى حَاجَة خَفِيفَة وِمُسَلِّيَة مُشْ هَيْقْدِرْ يِرَكِّزْ فِي حَاجَة مُعَقَّدَة خَالِصْ",
"0_01604_01": "فِيهَا شَخْصِيَّاتْنَا أُسْلُوبْ حَيَاتْنَا وِحَتَّى فِلْسُفْتْنَا فِي اِلْفُلُوسْ هِيَ",
"0_02764_00": "كُلُّهْ كَانْ مُتَخَيِّلْ إِنَّ اِلْإِجَابَاتْ هَتْبْقَى جَاهِزَة فِي اِلْكِتَابْ وِهَيْدْخُلُوا يِنْقِلُوهَا وِيْخْرُجُوا لَكِنْ اِلصَّدْمَة كَانَتْ عَنِيفَة",
"0_03085_01": "اِلشَّايْ اِلْأَخْضَرْ بِاللِّمُونْ وِالْكُمُّونْ بِالْجِنْزَبِينْ هَلْ اِلْحَاجَاتْ دِي بِتْسِيحْ اِلْكِرِشْ فِعْلَاً؟",
"0_03309_01": "مُشْ اِلْمَفْرُوضْ نِتْخَلَّصْ مِنْهَا وِخْلَاصْ طَالَمَا هِيَ مَوْجُودَة؟",
"0_03334_01": "يِقْتُلْ اِلْمِيكْرُوبْ دَهْ اِلتَّقْرِيرْ بِيطْلَعْ يِقُولْ إِنَّ اِلْمِيكْرُوبْ",
"0_03407_01": "هُوْ إِنِّنَا نِفَكِّكْ اِلْمَفَاهِيمْ دِي وِنِبِّصْ عَلَيْهَا بِعَيْنْ عِلْمِيَّة بَعِيدَاً بَقَى عَنْ أَيِّ وِصْمَة اِجْتِمَاعِيَّة",
"0_03612_01": "اِلْبُولْ وِبِيخَلِّيهْ غَامِقْ جِدَاً زَيْ اِلْكُوكَاكُولَا صُورَة مُرْعِبَة بِصَرَاحَة",
"0_03618_01": "اِلْلِي هِيَ اِلْفَرَقْ بَيْنْ حَامِلْ لِلْمَرَضْ وِمَرِيضْ وِدِي مُهِمَّة أَوِّي اِلنَّاسْ تِفْهَمْهَا إِيهْ اِلْفَرَقْ بَيْنْهُمْ؟",
"0_03961_00": "يَعْنِي اِلْخِلَاصَة إِنِّ جِسْمِنَا فِيهْ زَيْ قَلَبْ اِحْتِيَاطِي فِي رِجْلَيْنَا وِإِحْنَا مُشْ بِنِسْتَخْدِمُهْ لَمَا بِنْبْقَى عَادِيْينْ؟",
"0_04351_00": "رَبَطْتُهْ بَيْنْ اِلْأُذُنْ وِالدُّوخَة أَغْلَبْنَا لَمَا بِيْحِسْ بِدُّوخَة بِيْقُولْ ضَاقْتِي وَاطِي أَوْ عِنْدِي أَنِيمِيا",
"0_04822_00": "وِ هُوْ اِلْاِنْسِيَاقْ وَرَاء اِلتِّرِنْدَاتْ اوِ اِلْمَوْضَة فِي اِلْمَشَارِيعْ.",
"0_05193_03": "اِلْعَائِلَاتْ دِي غَالِبَاً مُشْ بِتْدُورْ عَلَى سَكَنْ مُؤَقَّتْ سَنَة وِلَا اِتْنِينْ وِ تَمْشِيْ.",
"0_05279_01": "تَمَامْ وِ اِبِلْ مَا نِخْتِمْ اِلْمَصَادِرْ بِتْقَدِّمْ مَجْمُوعَة نَصَايِحْ سَرِيعَة كِدَهْ. كَأَنَّهَا خَلَاصَة رِحْلَة اِلْوُصُولْ لِأَوَّلْ مِيتْ عَمِيلْ.",
"0_06296_00": "وِ خُصُوصَاً اِلْلِي بِيْفَكِّرُوا فِي تَسْعِيرْ شُغْلْهُمْ أَوْ مُنْتَجَاتْهُمْ.",
"0_06769_01": "اِلْمَصَادِرْ بِتِنْتَقِدْ فِكْرَة اِلْقَائِدْ اِلسُوبَرْمَانْ اِلْلِي بِيْعَمَلْ كُلْ حَاجَة بِنَفْسُهْ.",
"0_06915_02": "مُمْكِنْ اِلْمَصَادِرْ بِتِطْرَحْ أَفْكَارْ زَيْ مَثَلَاً اِلشِّرَاء اِلْمُشْتَرَكْ مَعْ صَدِيقْ أَوْ قَرِيبْ.",
"0_07008_00": "مُقَارْنَة بَيْنْ فُرَصْ وِ تَحَدِّيَاتْ اِلْاِسْتِثْمَارْ فِي اِلْمُدُنْ اِلْجَدِيدَة اوصَادْ اِلْأَحْيَاء اِلْقَدِيمَة.",
"0_07066_01": "مُشْ كُلْ فِكْرَة مَشْرُوعْ مَكْتُوبْ لَهَا اِلنِّجَاحْ وِ اِلْاِسْتِمْرَارْ.",
"0_07324_01": "أَوْ يِمْكِنْ سُؤَالْ تَانِي لِلتَّفْكِيرْ أَشْرُوعْنَا.",
"0_07642_00": "وِ آخِرْ نُقْطَة أَوْ اِسْتِرَاتِيجِيَّة اِلْمُلَاحَظَاتْ بِتْرَكِّزْ عَلَيْهَا. عَشَانْ نِحَافِظْ عَلَى اِلدَّافِعِيَّة دِي أَوْ عَلَى اِلْأَقَلْ نِخَلِّيهَا مَوْجُودَة.",
"0_08303_01": "حَسَبْ اِلتَّحْلِيلَاتْ دِي؟ فِيهْ كِذَّا عَامِلْ رَئِيسِي بِيتْكَرِّرْ فِي كُلْ اِلْمَصَادِرْ تَقْرِيبَاً أَوَّلَاً سُهُولَة",
"0_08715_00": "أَئِدِمْ حَتَّى مِنْ اِللُّغَة وِ اِلْعَقْلْ وِ اِلْأَسْمَاء اِلْلِي بِتَحَدِّد هُوِيَّاتْنَا. دِي دِي فِكْرَة اوِّيَة جِدَاً.",
"0_08816_02": "يَعْنِي اِلْحُرِّيَّة دِي اِصَادَهَا مَسْئُولِيَّة أَكْبَرْ فِي اِلْإِدَارَة اِلْيَوْمِيَّة؟ تَمَامَاً، هِيَ مُشْ حُرِّيَّة مُطْلَقَة.",
"0_08823_01": "يَعْنِي مُشْ كُلْ اِلْعِمَارَاتْ أَوْ اِلْكُومْبَاوُنْدَاتْ بِتْقَبِّلْ فِكْرَة إِنِّ فِيهْ نَاسْ غُرَبَاء دَاخِلِينْ طَالِعِينْ كُلْ شُوَيَّة.",
"0_09177_00": "اِلتَّوْصِيَة كَانَتْ وَاضْحَة وِمُبَاشِرَة: بِلَاشْ تِبْدَأْ مَشْرُوعْ وِ إِنْتْ غَرْقَانْ فِي دُيُونْ مُشْ قَادِرْ عَلَيْهَا.",
"1_00919_00": "فِي دِرَاسَاتْ كَتِيرْ إِثْبَتَّتْ أَنُّ وُجُودْهُمْ بِيقَلِّلْ اِلتَّوْتُرْ وِالْقَلَقْ وِالْاِكْتِئَابْ وُجُودْهُمْ فِي حَدْ",
"1_01068_01": "إِحْنَا اِلْلِي مُسَيْطِرِينْ عَلَى اِلتُّرُولِّيْ مُشْ هُوَ اِلْلِي بِيْسِيْطِرْ عَلَيْنَا وِدَهْ بِيْطَرَحْ سُؤَالْ أَخِيرْ لِلتَّفْكِيرْ",
"1_01198_01": "دِي اِلتَّقْرِيرْ بِيْوَصِفْهَا بِشَكْلْ كُومِيدِيْ هُوِّيْ بِيْسَمِّيهَا مَرْحَلَة اِلْأَنْتِخَة اِلْأَنْتِخَة اِلْإِجْبَارِيَّة",
"1_01731_00": "اِلْعَرَبِيَّة دِي بِتْبْقَى زَيْ اِلسِّمْ فِي اِلْعَسَلْ شَكْلْهَا حِلُو لَكِنْ مِحَدِّشْ هَيْقْبِلْ يِشْتَرِيهَا مِنِّكْ أَبَدَاً لُو كَشَفْ",
"1_01812_00": "اِلْلِي اِلتَّقْرِيرْ وَصَفُهْ بِإِنُّهْ هَمْزَة اِلْوَصْلْ اِلْحَيَوِيَّة.",
"1_02493_00": "مُهِمَّتْنَا هِيَ نِفْهَمْ إِيهْ سِرِّ اِلْاِحْتِفَالْ دَهْ،",
"1_02548_01": "عُمِرْنَا مَوْقِفْنَا وِفَكِّرْنَا فِي تَفَاصِيلِهْ مَعَانَا تَقْرِيرْ عُنْوَانِهْ فِي سَرْدِيقْ اِلْعَزَاء وَاجِبْ وِالْمَنْزَارَة",
"1_03905_00": "تِكْسِيرْ اِلْعَضِمْ وِالْأَرْقْ صَحْ بَسْ كُلْ اِلْأَعْرَاضْ دِي لَهَا أَدْوِيَّة وِمُسَكِّنَاتْ بِتْسَاعِدْ اِلْمَرِيضْ يِعَدِّيهَا",
"1_03966_00": "لَكِنْ اِلتَّقْرِيرْ بِيْنَبِّهْ لُو اِللَّوْنْ تِحَوِّلْ لِأَبْيَضْ شَاحِبْ زَيْ اِلشِّمَعْ أَوْ أَزْرَقْ غَامِقْ جِدَاً",
"1_03983_01": "سِبَا سِبَا مُوسِيقَى هَادِيَّة زَيُوطْ عِطْرِيَّة وِشُوَيَّة مَسَّاجْ وِخْلَاصْ وِهِيَ دِي اِلْمُشْكِلَة",
"1_04796_01": "اِلْلِي شَافْهَا بِعَيْنِهْ. اِلْحَلِّ طَلَعْ كَرَدْ فِعْلْ طَبِيعِيْ لِلْاِحْتِيَاجْ دَهْ.",
"1_05155_01": "رَابِعَاً اِلْبَخِلْ اِلشَّدِيدْ أَوْ اِلْمُحَاسَبَة عَلَى كُلْ فَتْفُوتَة فِي اِلْأَوَّلْ.",
"1_06615_02": "اِلْمَصْدَرْ أَكَّدْ عَلَيْهَا جِدَاً إِنَّ اِلْوَاحِدْ يِبْنِيْ أَوْ يِسْتَعِينْ بِشَبَكَة دَعْمْ إِيجَابِيَّة حَوَالِيْهْ.",
"1_07516_01": "وِ كُلْ مَبْنَى بِنْعَدِّي جَنْبُهْ كُلْ يُومْ، مِنْ أَصْغَرْ بَيْتْ لِأَكْبَرْ بُرْجْ. هُوَ جُزْء مِنْ قِصَّة كَبِيرَة بِتِتْكَتَبْ بِلُغَة مُعَيَّنَة.",
"1_07767_01": "اِلنَّاسْ بِتِحْتَرِمْ اِلصَّرَاحَة اِلْلِي بِتِيجِيْ مَعْ خُطَّة عَمَلْ وَاضْحَة. فِهِمْتُكْ, يِبْقَى كِدَهْ فِهِمْنَا اِلْجُمْهُورْ.",
"1_07786_00": "اِلْبَرْنَامِجْ دَهْ هَيْسَاعِدِكْ تِبْنِيْ عَيْنْ فَنِّيَّة اوِّيَة. وِ تِعْمَلْ بُورْتِفُولْيُو مُحْتَرِمْ يِفْتَحْ لَكْ ابَوَابْ شُغْلْ جَدِيدَة.",
"1_08003_00": "مُمْكِنْ جِدَاً, اِلْبْرَانْدْ نِقْدِرْ نِقُولْ إِنُّهْ بِيْسَاوِيْ: اِنْطِبَاعْ زَائِدْ إِحْسَاسْ زَائِدْ اِلْتِزَامْ. اِلْاِنْطِبَاعْ, اِلْاِنْطِبَاعْ اِلْلِي بِتْسِيبُهْ.",
"1_08227_02": "مُمْكِنْ تِكُونْ بِتْبِيعْ سِلْعَة، مُنْتَجْ يَعْنِيْ نِقْدِرْ نِقُولْ نَمَطِيْ بِيتْكَرِّرْ.",
"1_09164_00": "آهْ، نَاسْ كَتِيرْ بِتْقَعْ فِيهْ. بِيْفَضِّلُوا يِخَطِّطُوا وِ يِطَوِّرُوا وِ يِصْرِفُوا وِ يِأَجِّلُوا خُطْوَة اِلْإِطْلَاقْ لِلسُّوقْ.",
"1_09198_01": "مِينْ فِيهُمْ اِلْلِي يَعْنِيْ مَكْسَبُهْ أَحْسَنْ؟\" أَوْ تِلَاقِي حَدْ تَانِيْ مُحْتَارْ يِقُولْ: \"طَبْ اِلْمَكَاتِبْ دِيْ سُوقْهَا شَغَالْ؟",
}
